[ExtensionOf(formStr(HcmJob))]
internal final class NVHcmJob_Extension
{
    public NumberSeqFormHandler numberSeqFormHandler;

}

Method.Source:
public void copyCustomJobIdToStandardJobId(FormDataSource _hcmJob_ds)
{
    HcmJob locHcmJob = _hcmJob_ds.cursor();

    if (locHcmJob.NVHcmJobNumSequence && !locHcmJob.JobId)
    {
        locHcmJob.JobId = locHcmJob.NVHcmJobNumSequence;

        _hcmJob_ds.object(fieldNum(HcmJob, JobId)).setValue(locHcmJob.JobId);
    }
}

public NumberSeqFormHandler numberSeqFormHandler()
{
    if(!numberSeqFormHandler)
    {
        numberSeqFormHandler = NumberSeqFormHandler::newForm(
            NVNumberSeqApplicationModuleHRM::getHcmJobNumSeqRef().NumberSequenceId, this, this.HcmJob_ds, fieldNum(HcmJob, NVHcmJobNumSequence));
    }
    return numberSeqFormHandler;
}

[FormDataFieldEventHandler(formDataFieldStr(HcmJob, HcmJob, NVHcmJobNumSequence), FormDataFieldEventType::Modified)]
public static void JobId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource fds = sender.datasource();

    fds.object(fieldNum(HcmJob, JobId)).setValue(sender.getValue());
}

[DataEventHandler(tableStr(HcmJob), DataEventType::Inserting)]
public static void HcmJob_onInserting(Common sender, DataEventArgs e)
{
    HcmJob job = sender as HcmJob;

    if(job.JobId == '')
    {
        job.JobId = job.NVHcmJobNumSequence;
    }
}

