[FormDataSourceEventHandler(formDataSourceStr(HcmJob, HcmJob), FormDataSourceEventType::Creating)]
public void HcmJob_OnCreating(FormDataSource sender, FormDataSourceEventArgs e)
{
    this.numberSeqFormHandler().formMethodDataSourceCreatePre();


}

[FormDataSourceEventHandler(formDataSourceStr(HcmJob, HcmJob), FormDataSourceEventType::Created)]
public void HcmJob_OnCreated(FormDataSource sender, FormDataSourceEventArgs e)
{
    this.numberSeqFormHandler().formMethodDataSourceCreate();

    this.copyCustomJobIdToStandardJobId(sender);
}

